begin;
do $$begin if current_setting('aroma.test_mode',true) is distinct from 'local-fixture' then raise exception 'Only local fixtures.';end if;end $$;
create schema aroma_site_test;
grant usage on schema aroma_site_test to anon,authenticated;
create function aroma_site_test.ok(p boolean,label text) returns text language plpgsql as $$begin if p is distinct from true then raise exception 'FAIL: %',label;end if;return 'PASS: '||label;end;$$;
create function aroma_site_test.error(statement text,state text,label text) returns text language plpgsql as $$declare actual text;begin begin execute statement;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from state then raise exception 'FAIL: %, got %',label,actual;end if;return 'PASS: '||label;end;$$;
create function aroma_site_test.document() returns jsonb language sql immutable as $$select '{"demonstration":true,"business":{"name":"SQL store","legalName":"SQL example","taxId":"","address":"SQL address"},"contact":{"whatsapp":"51912345678","email":"contact@example.invalid","hours":"SQL hours"},"social":{"instagram":"","facebook":"","tiktok":""},"policies":{"privacy":"SQL privacy","terms":"SQL terms","returns":"SQL returns"}}'::jsonb$$;
grant execute on all functions in schema aroma_site_test to anon,authenticated;
insert into auth.users(id,email) values('e1000000-0000-4000-8000-000000000001','site-admin@example.invalid'),('e1000000-0000-4000-8000-000000000002','site-customer@example.invalid');
insert into private.admin_memberships(user_id,active) values('e1000000-0000-4000-8000-000000000001',true);
set local role anon;
select aroma_site_test.ok(api.site_settings()->>'version'='0','Unconfigured store has explicit version zero');
select aroma_site_test.error('select * from app.site_settings','42501','Public cannot read store rows directly');
select aroma_site_test.error('select api.admin_save_site_settings(aroma_site_test.document(),0)','42501','Anonymous cannot save store settings');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","aal":"aal2"}',true);
set local role authenticated;
select aroma_site_test.error('select api.admin_save_site_settings(aroma_site_test.document(),0)','42501','Customer cannot save store settings');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
set local role authenticated;
select aroma_site_test.error('select api.admin_save_site_settings(aroma_site_test.document(),0)','42501','Admin without MFA cannot save');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
set local role authenticated;
select aroma_site_test.ok(api.admin_save_site_settings(aroma_site_test.document(),0)->>'version'='1','Admin saves one versioned public document');
select aroma_site_test.error('select api.admin_save_site_settings(aroma_site_test.document(),0)','PT409','Concurrent stale edit cannot overwrite current settings');
select aroma_site_test.error('select api.admin_save_site_settings(aroma_site_test.document()||''{"privateSecret":"forbidden"}''::jsonb,1)','22023','Unknown private fields rejected');
select aroma_site_test.error('select api.admin_save_site_settings(jsonb_set(aroma_site_test.document(),''{social,instagram}'',''"https://evil.invalid/user"''),1)','22023','Social links reject offsite destinations');
select aroma_site_test.error('select api.admin_save_site_settings(jsonb_set(aroma_site_test.document(),''{demonstration}'',''false''),1)','22023','Example identity cannot be marked ready');
select aroma_site_test.ok(api.admin_save_site_settings(jsonb_set(aroma_site_test.document(),'{social,instagram}','"https://www.instagram.com/aroma_example/"'),1)->>'version'='2','Official-domain social URL is accepted');
reset role;
set local role anon;
select aroma_site_test.ok(api.site_settings()#>>'{data,business,name}'='SQL store','Public projection follows saved store identity');
select aroma_site_test.ok(not(api.site_settings()?'updated_by'),'Public projection excludes administrator metadata');
reset role;
rollback;
